-- ============================================================
--  football_quiz_seed.sql — Football quiz content import
--  (FOOTBALL-QUIZ-DATABASE.md, 997 reviewed questions)
--  NOT applied automatically. Nothing in this repo runs this file — review
--  it, then paste the WHOLE thing into the Supabase SQL Editor (project
--  qxfcwsiysnjxhxljqigl).
--
--  APPLY ORDER: run AFTER supabase/quiz_category_isolation.sql is live
--  (this file inserts rows with category = 'Football', which only the
--  category-aware quiz RPCs from that migration know how to pool).
--
--  Run BLOCK 1 first (entirely read-only — SELECTs only, zero writes) and
--  review the output. Only after that looks right, run BLOCK 2 (the single
--  INSERT transaction).
--
--  PURE INSERT, no deactivation: unlike ufc_quiz_seed.sql (which flips
--  is_active=false on legacy pre-existing UFC rows before inserting),
--  there are NO pre-existing quiz_questions rows with category='Football'.
--  BLOCK 2 therefore contains no UPDATE/deactivation step at all — it is
--  one INSERT, guarded idempotent.
--
--  Idempotent / safe to re-run BLOCK 2 as many times as you like:
--   - the INSERT is guarded by an "already applied?" check: if any active
--     category='Football' row already exists, the whole DO block is
--     skipped (a true no-op), not just a duplicate-safe insert.
--   - belt and suspenders: the INSERT also carries a `where not exists
--     (...)` keyed on (question, level, category), matching only
--     is_active = true rows.
--   - the whole thing runs inside one BEGIN/COMMIT, so a failure partway
--     through (e.g. a type mismatch in one VALUES row) cannot leave a
--     partial import committed.
--
--  Source: every question/option string below is copied verbatim
--  (byte-for-byte) from FOOTBALL-QUIZ-DATABASE.md — nothing translated,
--  reworded, shortened, re-ordered or invented. Dollar-quoting ($gq$...$gq$)
--  is used instead of '...' so embedded double quotes/apostrophes in the
--  source text need no escaping. Verified: the source file contains no
--  literal "$gq$" substring, so this delimiter cannot collide with content.
--
--  Mapping (per the 997-question source):
--   - level = 'მარტივი' for questions 1-200, 'საშუალო' for 201-698,
--     'რთული' for 699-997 (all three section boundaries verified against
--     the source's own headers, not hardcoded by number range alone).
--   - options = the 4 choices A-D in the SAME order as the source
--     (already shuffled during review; NOT re-shuffled here) via
--     to_jsonb(ARRAY[...]::text[]), matching ufc_quiz_seed.sql exactly.
--   - correct_index = 0-based index of the option marked with ✅ in the
--     source (A->0, B->1, C->2, D->3).
--   - "Mixed" (შერეული) level: NOT stored as rows here, same as UFC. It is
--     a query-time sentinel handled by get_ai_quiz_questions /
--     create_quiz_room (quiz_category_isolation.sql + quiz_no_repeat.sql).
-- ============================================================


-- ============================================================
-- BLOCK 1 — DRY RUN / PREVIEW (read-only — no INSERT/UPDATE/DELETE below
-- this point until BLOCK 2). Safe to run anytime, as many times as you like.
-- ============================================================

-- 1a. Current state, before any change. Expect zero category='Football'
-- rows (none exist yet) and the existing category='UFC' rows unaffected.
select 'quiz_questions BEFORE' as what, category, level, is_active, count(*) as n
from public.quiz_questions
group by category, level, is_active
order by 1, 2, 3, 4;

-- 1b. "Already applied?" guard preview. Must be false before a first run
-- (no category='Football' row can exist yet).
select 'already applied? (must be false before first run)' as what,
  exists (
    select 1 from public.quiz_questions where category = 'Football' and is_active = true
  ) as already_applied;

-- 1c. New quiz_questions rows this migration would insert, per level, plus
-- an internal self-collision check across this migration's own 997 rows
-- (expect 0 rows from the second query — this is a pure insert with no
-- pre-existing Football rows to collide with, so the only possible
-- collision is within the 997 rows themselves).
select level, count(*) as n
from (
  values
  ($gq$რომელი ქვეყნის ნაკრებმა მოიგო პირველი მსოფლიო ჩემპიონატი 1930 წელს?$gq$, $gq$მარტივი$gq$),
