-- ============================================================
-- BLOCK 2 — WRITES (run only after reviewing BLOCK 1's output)
-- ============================================================

-- A single transaction, guarded by an "already applied?" check so a
-- second run is a true no-op. PURE INSERT: no pre-existing Football rows
-- to deactivate (unlike ufc_quiz_seed.sql's legacy UFC rows), so there is
-- no UPDATE/deactivation step here at all.
begin;

do $football_seed$
declare
  v_already_applied boolean;
begin
  select exists (
    select 1 from public.quiz_questions where category = 'Football' and is_active = true
  ) into v_already_applied;

  if v_already_applied then
    raise notice 'football_quiz_seed: content already active -- insert skipped (no-op).';
    return;
  end if;

  -- Insert all 997 Football quiz questions (idempotent: skips any row
  -- whose exact question text + level + category already exists).
  insert into public.quiz_questions (question, options, correct_index, level, category, is_active)
  select v.question, v.options, v.correct_index, v.level, 'Football', true
  from (
    values
  ($gq$რომელი ქვეყნის ნაკრებმა მოიგო პირველი მსოფლიო ჩემპიონატი 1930 წელს?$gq$, to_jsonb(ARRAY[$gq$არგენტინა$gq$, $gq$იტალია$gq$, $gq$ბრაზილია$gq$, $gq$ურუგვაი$gq$]::text[]), 3, $gq$მარტივი$gq$),
