  ($gq$ვის ეკუთვნის ჩემპიონთა ლიგის ერთ სეზონში გატანილი გოლების რეკორდი (17 გოლი)?$gq$, to_jsonb(ARRAY[$gq$რობერტ ლევანდოვსკი$gq$, $gq$კრიშტიანუ რონალდუ$gq$, $gq$ქარიმ ბენზემა$gq$, $gq$ლიონელ მესი$gq$]::text[]), 1, $gq$მარტივი$gq$),
