  ($gq$ვინ არის დანიის ეროვნული ნაკრების ყველა დროის რეკორდსმენი ჩატარებული მატჩების რაოდენობით (კრისტიან ერიქსენმა სიმონ კიაერს გადაუსწრო — ვინ იყო რეკორდსმენი 2024 წლამდე 132 მატჩით)?$gq$, to_jsonb(ARRAY[$gq$თომას ჰელვეგი$gq$, $gq$დენის რომედალი$gq$, $gq$პეტერ შმეიხელი$gq$, $gq$სიმონ კიაერი$gq$]::text[]), 3, $gq$რთული$gq$),
  ($gq$რომელ ინგლისურ კლუბს აქვს მოგებული ინგლისის ჩემპიონატი პირველად 1888-1889 წლებში (ფეხბურთის ლიგის პირველი ჩემპიონი, რომელმაც სეზონი დაუმარცხებლად დაასრულა და იმავე წელს ასოციაციის თასიც მოიგო)?$gq$, to_jsonb(ARRAY[$gq$ვულვერჰემპტონ უონდერერსი$gq$, $gq$პრესტონ ნორთ ენდი$gq$, $gq$ასტონ ვილა$gq$, $gq$ბლექბერნ როვერსი$gq$]::text[]), 1, $gq$რთული$gq$),
  ($gq$რომელი ურუგვაელი ფეხბურთელი იყო ცნობილი მეტსახელით „ელ ლოკო“ (El Loco), რომელმაც 2010 წლის მსოფლიო ჩემპიონატზე განასთან პენალტი „პანენკას“ სტილში შეასრულა?$gq$, to_jsonb(ARRAY[$gq$სებასტიან აბრეუ$gq$, $gq$დიეგო ლუგანო$gq$, $gq$ალვარო პერეირა$gq$, $gq$მაქსი პერეირა$gq$]::text[]), 0, $gq$რთული$gq$),
  ($gq$რომელ წელს მოიგო „მაგდებურგმა“ (აღმოსავლეთ გერმანიის ერთადერთმა კლუბმა ევროპული ტიტულით) უეფას თასების მფლობელთა თასი ფინალში „მილანის“ დამარცხებით (2:0)?$gq$, to_jsonb(ARRAY[$gq$1973$gq$, $gq$1975$gq$, $gq$1972$gq$, $gq$1974$gq$]::text[]), 3, $gq$რთული$gq$),
  ($gq$რომელი გერმანული კლუბის ზედმეტსახელია „დინოზავრი“ (Der Dino — ბუნდესლიგაში უწყვეტად 55 წლის განმავლობაში თამაშის გამო 2018 წლამდე)?$gq$, to_jsonb(ARRAY[$gq$ვერდერი$gq$, $gq$შალკე 04$gq$, $gq$შტუტგარტი$gq$, $gq$ჰამბურგი$gq$]::text[]), 3, $gq$რთული$gq$),
  ($gq$ვინ მოიგო 1964 წლის „ოქროს ბურთი“?$gq$, to_jsonb(ARRAY[$gq$ეუსებიო$gq$, $gq$ამანსიო ამარო$gq$, $gq$დენის ლოუ$gq$, $gq$ლუის სუარესი (ესპანელი)$gq$]::text[]), 2, $gq$რთული$gq$),
  ($gq$რომელ სტადიონზე თამაშობს საშინაო მატჩებს ესპანური კლუბი „ლევანტე“?$gq$, to_jsonb(ARRAY[$gq$სიუდად დე ვალენსია (Ciutat de València)$gq$, $gq$მარტინეს ვალერო$gq$, $gq$მესტალია$gq$, $gq$ესტადიო დე ლა სერამიკა$gq$]::text[]), 0, $gq$რთული$gq$),
  ($gq$რომელი მწვრთნელი ხელმძღვანელობდა ურუგვაის ნაკრებს 1950 წლის მსოფლიო ჩემპიონატის მოგებისას („მარაკანასო“)?$gq$, to_jsonb(ARRAY[$gq$ოსკარ ტაბარესი$gq$, $gq$ალბერტო სუპიჩი$gq$, $gq$ხუან ლოპეს ფონტანა$gq$, $gq$ონდინო ვიერა$gq$]::text[]), 2, $gq$რთული$gq$),
  ($gq$რომელ კლუბში თამაშობდა ენცო ფერნანდესი „ჩელსიში“ გადასვლამდე 2023 წლის იანვარში?$gq$, to_jsonb(ARRAY[$gq$დეფენსა ი ხუსტისია$gq$, $gq$პორტუ$gq$, $gq$რივერ პლეიტი$gq$, $gq$ბენფიკა$gq$]::text[]), 3, $gq$რთული$gq$),
  ($gq$რომელი ფეხბურთელია ყველაზე მეტი გოლის ავტორი ერთ მსოფლიო ჩემპიონატზე პორტუგალიის ნაკრების რიგებში (9 გოლი 1966 წელს, მათ შორის 4 გოლი ჩრდილოეთ კორეის კარში 0:3 ჩამორჩენის შემდეგ 5:3 მოგებულ მატჩში)?$gq$, to_jsonb(ARRAY[$gq$ეუსებიო$gq$, $gq$გონსალო რამოში$gq$, $gq$კრიშტიანუ რონალდუ$gq$, $gq$პაულეტა$gq$]::text[]), 0, $gq$რთული$gq$),
  ($gq$რომელ იტალიურ კლუბში თამაშობდა ფილიპო ინძაგი „მილანში“ გადასვლამდე 2001 წელს (1997-2001 წლებში)?$gq$, to_jsonb(ARRAY[$gq$იუვენტუსი$gq$, $gq$პიაჩენცა$gq$, $gq$პარმა$gq$, $gq$ატალანტა$gq$]::text[]), 0, $gq$რთული$gq$),
  ($gq$რომელი ქვეყნის ნაკრებმა მოიგო 1995 წლის ფიფას კონფედერაციათა თასი ფინალში არგენტინის დამარცხებით (2:0)?$gq$, to_jsonb(ARRAY[$gq$ბრაზილია$gq$, $gq$ნიგერია$gq$, $gq$დანია$gq$, $gq$მექსიკა$gq$]::text[]), 2, $gq$რთული$gq$)
  ) as v(question, options, correct_index, level)
  where not exists (
    select 1 from public.quiz_questions e
    where e.question = v.question and e.level = v.level and e.category = 'Football' and e.is_active = true
  );
end;
$football_seed$;

commit;

-- 2d. Post-write check — run after BLOCK 2 to confirm the new state.
select 'quiz_questions AFTER' as what, category, level, is_active, count(*) as n
from public.quiz_questions
group by category, level, is_active
order by 1, 2, 3, 4;
